561:function skepticRole(rung, workerReport, round) {
619:function repairPrompt(rung, verdict, decision) {
651:function judgeRole(kind, rung, worker, verdict, extra) {
697:const JUDGE_SCHEMA = {
713:const RUNG_SCHEMA = {
736:const SKEPTIC_SCHEMA = {
762:const MAIN_TREE_ROLE = [
770:function gatherRole(approved, notLanded) {
