903:const ATOMIC_OTHER = 'atomic0 atomic1 atomic2 atomic3 atomic4 atomic5 atomic6 nestedTransactions0 nestedTransactions1 nestedTransactions2'
904:const ATOMIC_COMPILER = 'AtomicTopLevelObjectVar AtomicTopLevelVar MutableTopLevelVarInLoop'
906:function gateRole(expectedMoves, expectedChecker) {
1099:const GATE_SCHEMA = {
1118:function mergedRepairRole(decision, kind) {
1131:function commitRole(gather, gate) {
1155:const COMMIT_SCHEMA = {
1178:  (rung) => agent(PREFIX + rungRole(rung) + rung.tail, {
1193:      judgeOnStop = await agent(PREFIX + judgeRole('stop', rung, worker, null, null), {
1201:      const resumed = await agent(PREFIX + rungRole(rung) + rung.tail + repairPrompt(rung, null, judgeOnStop), {
1213:    const verdict = await agent(PREFIX + skepticRole(rung, worker, 1), {
1226:    const decision = await agent(PREFIX + judgeRole('refusal', rung, worker, verdict, null), {
1238:    const repaired = await agent(PREFIX + rungRole(rung) + rung.tail + repairPrompt(rung, verdict, decision), {
