import json, sys, datetime
def ts(s): return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
for p in sys.argv[1:]:
    msgs={}; order=[]; ntool=0; first=last=None; tool_ids=set(); models=set(); nlines=0
    for line in open(p):
        nlines+=1
        d=json.loads(line)
        t=d.get('timestamp')
        if t:
            tt=ts(t); first=tt if first is None else min(first,tt); last=tt if last is None else max(last,tt)
        if d.get('type')=='assistant':
            m=d['message']; mid=m.get('id'); u=m.get('usage') or {}
            models.add(m.get('model'))
            if mid not in msgs:
                msgs[mid]=dict(u); order.append(mid)
            else:
                if (u.get('output_tokens') or 0)>(msgs[mid].get('output_tokens') or 0): msgs[mid]['output_tokens']=u.get('output_tokens')
            for c in m.get('content') or []:
                if isinstance(c,dict) and c.get('type')=='tool_use' and c['id'] not in tool_ids:
                    tool_ids.add(c['id']); ntool+=1
    g=lambda k: sum((msgs[i].get(k) or 0) for i in order)
    inp,cc,cr,out=g('input_tokens'),g('cache_creation_input_tokens'),g('cache_read_input_tokens'),g('output_tokens')
    lu=msgs[order[-1]]
    final=(lu.get('input_tokens') or 0)+(lu.get('cache_creation_input_tokens') or 0)+(lu.get('cache_read_input_tokens') or 0)
    fu=msgs[order[0]]
    print(p.split('/')[-1], 'lines',nlines,'requests',len(order),'toolcalls',ntool,'models',sorted(models))
    print('  input',inp,'cache_write',cc,'cache_read',cr,'output',out,'processed',inp+cc+cr+out)
    print('  final_ctx',final,'+final_out',final+(lu.get('output_tokens') or 0),'first_req in/cw/cr',fu.get('input_tokens'),fu.get('cache_creation_input_tokens'),fu.get('cache_read_input_tokens'))
